{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE Sale_productivity_GT AS WITH ps_base AS ( SELECT ps.*, ROUND(ps.REVENUE / 100000, 2) AS Adj_Revenue, CASE WHEN UPPER(TRIM(ps.product_type)) = \'EVERYDAY\' THEN \'Everyday\' ELSE \'Nutrition\' END AS Product, CASE WHEN ps.area_classification = \'Bangalore-GT\' THEN \'BLR\' WHEN ps.area_classification = \'Hyderabad-GT\' THEN \'HYD\' ELSE \'NCR\' END AS Zones, TO_DATE(ps.date) AS clean_date FROM primary_and_secondary_sku ps WHERE ps.retailer_type = \'Distributor\' AND ps.REVENUE IS NOT NULL AND TO_DATE(ps.date) >= \'2025-04-01\' ), mtd_calc AS ( SELECT Zone, Product, DATE_TRUNC(\'month\', clean_date) AS month_start, SUM(Adj_Revenue) AS actual_mtd, MAX(DAY(clean_date)) AS days_elapsed, DAY(LAST_DAY(DATE_TRUNC(\'month\', clean_date))) AS total_days_in_month, ROUND( SUM(Adj_Revenue) * ( DAY(LAST_DAY(DATE_TRUNC(\'month\', clean_date))) / NULLIF(MAX(DAY(clean_date)), 0) ), 2 ) AS projected_mtd FROM ps_base WHERE DATE_TRUNC(\'month\', clean_date) = DATE_TRUNC(\'month\', CURRENT_DATE) GROUP BY Zone, Product, DATE_TRUNC(\'month\', clean_date) ) SELECT ps_base.*, tg.date AS target_date, tg.area, tg.type, tg.amount, tg.amount_in_lakhs, tg.parameter, mtd_calc.actual_mtd, mtd_calc.projected_mtd, CASE WHEN DATE_TRUNC(\'month\', ps_base.clean_date) != DATE_TRUNC(\'month\', CURRENT_DATE) THEN NULL WHEN tg.amount_in_lakhs IS NULL OR tg.amount_in_lakhs = 0 THEN NULL ELSE ROUND((mtd_calc.actual_mtd / tg.amount_in_lakhs) * 100, 2) END AS achievement_percent FROM ps_base LEFT JOIN bi__target_gt tg ON DATE_TRUNC(\'month\', ps_base.clean_date) = DATE_TRUNC(\'month\', tg.clean_date) AND ps_base.Zone = tg.area AND UPPER(ps_base.Product) = UPPER(tg.parameter) LEFT JOIN mtd_calc ON ps_base.Zone = mtd_calc.Zone AND ps_base.Product = mtd_calc.Product AND DATE_TRUNC(\'month\', ps_base.clean_date) = mtd_calc.month_start; CREATE OR REPLACE TABLE Secondary_sales_Productivity_GT AS SELECT sec.date, sec.retailer_name, sec.AREA_CLASSIFICATION, sec.BEAT_NUMBER_ORIGINAL, sec.SALE_TYPE, map.\"SO Name\", map.\"Dealer name\", map.franchise, map.platinum, sum(CASE WHEN map.platinum=\'Y\' THEN 4 ELSE 2 END) AS \"Target_BillCut\", CASE WHEN DAY(sec.DATE) BETWEEN 1 AND 7 THEN \'1-7th\' WHEN DAY(sec.DATE) BETWEEN 1 AND 14 THEN \'1-14th\' WHEN DAY(sec.DATE) BETWEEN 1 AND 21 THEN \'1-21th\' ELSE \'LastWeek\' END AS date_bracket, SUM(sec.REVENUE) AS total_revenue, SUM(sec.EGGS_SOLD) AS total_eggs_sold, COUNT(*) AS bill_count FROM primary_and_secondary AS sec Right JOIN BI__MAPPING AS map ON map.\"Dealer name\" = sec.retailer_name WHERE sec.DATE >= \'2025-04-01\' AND sec.SALE_TYPE = \'Secondary_sale\' GROUP BY sec.date, sec.retailer_name, sec.AREA_CLASSIFICATION, sec.BEAT_NUMBER_ORIGINAL, sec.SALE_TYPE, map.\"SO Name\", map.\"Dealer name\", map.franchise, map.platinum, CASE WHEN DAY(sec.DATE) BETWEEN 1 AND 7 THEN \'1-7th\' WHEN DAY(sec.DATE) BETWEEN 1 AND 14 THEN \'1-14th\' WHEN DAY(sec.DATE) BETWEEN 1 AND 21 THEN \'1-21th\' ELSE \'LastWeek\' END ORDER BY sec.retailer_name, date_bracket; CREATE OR REPLACE TABLE Sale_productivity_OFFMT AS WITH ps_OFFMT AS ( SELECT pss.*, ROUND(pss.REVENUE / 100000, 2) AS Adj_Revenue, TO_DATE(pss.date) AS clean_date FROM primary_and_secondary_sku pss WHERE LOWER(pss.area_classification) LIKE \'%of-mt%\' AND pss.REVENUE IS NOT NULL AND pss.date >= \'2025-04-01\' ), mtd_calc AS ( SELECT DATE_TRUNC(\'month\', clean_date) AS month_start, SUM(Adj_Revenue) AS actual_mtd, MAX(DAY(clean_date)) AS days_elapsed, DAY(LAST_DAY(DATE_TRUNC(\'month\', clean_date))) AS total_days_in_month, ROUND( SUM(Adj_Revenue) * ( DAY(LAST_DAY(DATE_TRUNC(\'month\', clean_date))) / NULLIF(MAX(DAY(clean_date)), 0) ), 2 ) AS projected_mtd FROM ps_OFFMT WHERE DATE_TRUNC(\'month\', clean_date) = DATE_TRUNC(\'month\', CURRENT_DATE) GROUP BY DATE_TRUNC(\'month\', clean_date) ), target_ofmt AS ( SELECT * FROM bi__target_gt WHERE LOWER(type) LIKE \'%mt%\' ) SELECT ps_OFFMT.*, tg.date AS target_date, tg.area, tg.type, tg.amount, tg.amount_in_lakhs, tg.parameter, mtd_calc.actual_mtd, mtd_calc.projected_mtd FROM ps_OFFMT LEFT JOIN target_ofmt tg ON DATE_TRUNC(\'month\', ps_OFFMT.clean_date) = DATE_TRUNC(\'month\', tg.clean_date) LEFT JOIN mtd_calc ON DATE_TRUNC(\'month\', ps_OFFMT.clean_date) = mtd_calc.month_start; CREATE OR REPLACE TABLE Tertiary_sales_Productivity_GT as SELECT * from tertiary_sales ts left join bi_tertiary bt on bt.dsr=ts.SALESPERSON_NAME where ts.status = \'created\' ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EGGOZDB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            